"""Whole-packet inventory and explicit available-versus-unprinted field scope."""
import collections,json
from sources import OUT,BASE,sha,save,original

def pin(p):return dict(path=str(p.relative_to(BASE)),bytes=p.stat().st_size,sha256=sha(p.read_bytes()))
def main():
 loc=json.loads((OUT/'printed-control-page-inventory.json').read_text());ovp=OUT/'source/original-page-scope-overviews.json';ov=json.loads(ovp.read_text());assert ov['page_count']==3238 and ov['source_count']==352
 seen=set();atlasby={}
